WITH lines AS (SELECT id, service, host, log_ts, level, latency_ms, status_code, k, value FROM app_logs LATERAL VIEW EXPLODE(context) t AS k, value) SELECT DATE_TRUNC('HOUR', log_ts) AS hour_window, CASE WHEN status_code >= 456 THEN 'HIGH' ELSE 'LOW' END AS status_code_tier, ROUND(SUM(latency_ms) / NULLIF(COUNT(CASE WHEN service = 'billing' THEN 1 END), 0), 2) AS latency_ms_per_billing, APPROX_PERCENTILE(latency_ms, ARRAY(0.25, 0.5, 0.75)) AS latency_ms_quartiles, ROUND(SUM(status_code) / NULLIF(COUNT(CASE WHEN level = 'INFO' THEN 1 END), 0), 2) AS status_code_per_info, BIT_AND(status_code) AS status_code_bit_and, SUM(status_code) FILTER (WHERE level = 'WARN') AS warn_total_status_code FROM lines GROUP BY DATE_TRUNC('HOUR', log_ts), CASE WHEN status_code >= 456 THEN 'HIGH' ELSE 'LOW' END;
